query:
mutation AddAzureKeyVault($subscriptionId: String!, $tenantId: String!, $clientId: String!, $clientSecret: String!, $enabled: Boolean, $schedule: String!, $applications: [Int!]) {
  addAzureKeyVault(
    subscriptionId: $subscriptionId
    tenantId: $tenantId
    clientId: $clientId
    clientSecret: $clientSecret
    enabled: $enabled
    schedule: $schedule
    applications: $applications
  ) {
    status
    msg
    __typename
  }
}
